import dayjs from '../src'
import utc from '../src/plugin/utc'
import timezone from '../src/plugin/timezone'
import customParseFormat from '../src/plugin/customParseFormat'
import advancedFormat from '../src/plugin/advancedFormat'
import weekOfYear from '../src/plugin/weekOfYear'
import weekYear from '../src/plugin/weekYear'
import duration from '../src/plugin/duration'
import '../src/locale/nl'
import '../src/locale/en-gb'
import '../src/locale/zh-cn'

dayjs.extend(utc)
dayjs.extend(timezone)
dayjs.extend(customParseFormat)
dayjs.extend(advancedFormat)
dayjs.extend(weekOfYear)
dayjs.extend(weekYear)
dayjs.extend(duration)

it('a) dayjs.tz with non-string input', () => {
  const d = new Date('2020-08-07T12:00-07:00')
  expect(dayjs.tz(d, 'America/Vancouver').format()).toBe('2020-08-07T12:00:00-07:00')
  expect(dayjs.tz(d.getTime(), 'America/Vancouver').format()).toBe('2020-08-07T12:00:00-07:00')
  expect(dayjs.tz(dayjs(d), 'America/Vancouver').format()).toBe('2020-08-07T12:00:00-07:00')
})

it('b) tz offset format', () => {
  expect(dayjs('2020-08-06T03:48:10.258Z').tz('Asia/Tokyo').format('Z')).toBe('+09:00')
})

it('c) nl ordinal', () => {
  expect(dayjs('2018-05-08').locale('nl').format('Do')).toBe('8ste')
  expect(dayjs('2018-05-19').locale('nl').format('Do')).toBe('19de')
})

it('d) weekYear en-gb', () => {
  expect(dayjs('2021-01-01').locale('en-gb').weekYear()).toBe(2020)
  expect(dayjs('2021-01-04').locale('en-gb').weekYear()).toBe(2021)
})

it('e) duration ms toISOString', () => {
  expect(dayjs.duration(1, 'ms').toISOString()).toBe('PT0.001S')
})

it('f) zh-cn customParseFormat round trip', () => {
  const format = 'YYYY年M月D日Ah点mm分ss秒'
  const s = dayjs('2018-05-02 01:02:03').locale('zh-cn').format(format)
  expect(dayjs(s, format).locale('zh-cn').format('YYYY-MM-DD HH:mm:ss')).toBe('2018-05-02 01:02:03')
})
